function add_default_implicit_resolvers(resolver::Resolver)
    for (tag, regex) in default_implicit_resolvers
        add_implicit_resolver(resolver, tag, regex)
    end
end

function add_implicit_resolver(resolver::Resolver, tag::String, regex::Regex)
    push!(resolver.implicit_resolvers, (tag, regex))
end

function resolve_scalar(value::String, resolver::Resolver)
    for (tag, regex) in resolver.implicit_resolvers
        if ismatch(regex, value)
            return (tag, value)
        end
    end
    return (DEFAULT_SCALAR_TAG, value)
end

function resolve_sequence(sequence::Vector, resolver::Resolver)
    resolved_sequence = [(resolve_scalar(item, resolver)...)[1] for item in sequence]
    return (DEFAULT_SEQUENCE_TAG, resolved_sequence)
end

function resolve_mapping(mapping::Dict, resolver::Resolver)
    resolved_mapping = Dict{String, Any}()
    for (key, value) in mapping
        resolved_key = resolve_scalar(key, resolver)[2]
        resolved_value = resolve_scalar(value, resolver)[2]
        resolved_mapping[resolved_key] = resolved_value
    end
    return

