"""
Lookup methods based on the provided expression and state.

    lookup(state::State, ex::Expr) -> Set{Method}
"""
function lookup(state::State, ex::Expr)
    codesource = lineinfo(ex)
    if ex.head == :call
        return findmethods(state, ex, codesource)
    elseif ex.head == :tuple
        return findtuples(state, ex)
    else
        return Set{Method}()
    end
end

# Lookup methods in the current module that match the given expression.
    function lookup(state::State, ex::Expr)
        # Check if the expression is a function call or a tuple.
        if ex.head == :call
            return findmethods(state, ex, (ex.line, ex.file))
        elseif ex.head == :tuple
            return findtuples(state, ex)
        else
            return Set{Method}()
        end
    end

