Base.isequal(a::Expr, b::Expr) = strip(a) == strip(b)

function test(exprs::Vector{Expr}, expected::Vector{Expr})
    for (i, expr) in enumerate(exprs)
        if !isequal(expr, expected[i])
            return false
        end
    end
    return true
end

