facts("GUITestRunner functionality tests") do
  context("Running tests and capturing results") do
    @fact not_throw(GUITestRunner.run_tests()) --> true "Tests run without throwing exceptions"
    results = GUITestRunner.run_tests()
    @fact length(results) --> 3 "Returns the correct number of test results"
    @fact all(r -> r.status in [:success, :failure], results) --> true "All results have valid statuses"
  end
  context("Test result formatting") do
    result = TestRunner.TestResult(:success, "Test passed")
    @fact GUITestRunner.format_result(result) --> "Test passed" "Formats success result correctly"
    result_failure = TestRunner.TestResult(:failure, "Test failed")
    @fact GUITestRunner.format_result(result_failure) --> "Test failed" "Formats failure result correctly"
  end
end

