        @fact colnames(re_cl) --> ["vector"]
        @fact_throws rename(cl, ["a", "b"])
    end

    context("change colnames with string") do
        @fact colnames(re_cls) --> ["string"]
        @fact_throws rename(cl, "string_a", "string_b")
    end
end

