    else
      Xrot = UV' * X;
      yrot = UV' * y;
      wt = 1.0 ./ sqrt(vc1 * evalV + vc0);
      Xnew = scale(wt, Xrot);
      ynew = wt .* yrot;
      b = Xnew \ ynew;
    end

    # return values
    return b, vc0, vc1, vc1_pvalue;

  elseif tests == "eScore"

    # fit the null model
    b = X \ y;
    r = y - X * b;
    vc0 = norm(r) ^ 2 / n;
