const BASE_URL = "https://api.sunlightfoundation.com"

function entity_search(entity_type::Symbol, query::String)
    url = "$BASE_URL/$entity_type/search?query=$query"
    response = Requests.get(url)
    return JSON.parse(String(response.body))
end

function entity_info(entity_type::Symbol, entity_id::String)
    url = "$BASE_URL/$entity_type/$entity_id"
    response = Requests.get(url)
    return JSON.parse(String(response.body))
end

function top_politicians(state::String, count::Int=10)
    url = "$BASE_URL/politicians/top?state=$state&count=$count"
    response = Requests.get(url)
    return JSON.parse(String(response.body))
end

function top_contributors(organization::String, count::Int=10)
    url = "$BASE_URL/contributors/top?organization=$organization&count=$count"
    response = Requests.get(url)
    return JSON.parse(String(response.body))
end

function top_industries(count::Int=10)
    url = "$BASE_URL/industries/top?count=$count"
    response = Requests.get(url)
    return JSON.parse(String(response.body))
end

function hom(G::SimpleGraph, H::SimpleGraph)::Union{Dict{Int, Int}, Nothing}
    for d in collect(Iterators.product(1:nv(G), repeat(1:nv(H), nv(G))))
        mapping = Dict(zip(1:nv(G), d))
        if hom_check(G, H, mapping)
            return mapping
        end
    end
    return nothing
end
